// Per-team season stat leaders.
//
// This file is REGENERATED by scripts/fetchStats.js from the Inside Lacrosse
// API (parse.bot). It starts empty because populating it requires a parse.bot
// API key (PARSE_API_KEY). Once you have a key:
//
//   PARSE_API_KEY=your-key npm run fetch-stats
//
// Until then STATS_LEADERS is empty and the Stat Leaders view falls back to
// listing each program's roster so recruits can still pull up film.
export const STATS_SEASON = null;
export const STATS_GENERATED_AT = null;
export const STATS_LEADERS = {};

export function getTeamLeaders(schoolId) {
  return STATS_LEADERS[schoolId] || [];
}

/** YouTube search URL so a recruit can pull up an athlete's film. */
export function filmSearchUrl(playerName, schoolName) {
  const q = encodeURIComponent(`${playerName} ${schoolName} lacrosse highlights`);
  return `https://www.youtube.com/results?search_query=${q}`;
}

export default STATS_LEADERS;
